// Package postgres is the PostgreSQL adapter of the API: it implements the
// persistence ports declared in the usecase package with pgx v5 and the code
// generated by sqlc (sqlcgen). SQL lives in queries/*.sql and is always
// parameterized; nothing here builds SQL from values.
//
// Rules the adapter enforces for every query (CLAUDE.md, ADR 0009/0013):
//   - business reads filter by company_id through usecase.Scope;
//   - soft deleted users and companies are never returned;
//   - optimistic concurrency uses the version column;
//   - the runtime role (api_app) only runs DML, never DDL.
package postgres

import (
	"context"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/bruno-blauzius/agent-planejador-pulverizacao/services/api/internal/adapter/postgres/sqlcgen"
	"github.com/bruno-blauzius/agent-planejador-pulverizacao/services/api/internal/usecase"
)

// connection is what a repository needs: run queries and open (nested)
// transactions. Both *pgxpool.Pool and pgx.Tx satisfy it; on a pgx.Tx, Begin
// creates a savepoint, so a failed statement does not poison the outer
// transaction.
type connection interface {
	sqlcgen.DBTX
	Begin(ctx context.Context) (pgx.Tx, error)
}

// Options are business values read from configuration.
type Options struct {
	// SessionTouchInterval is the minimum time between two writes of
	// auth_sessions.last_seen_at for the same session (0 writes every time).
	SessionTouchInterval time.Duration
}

// Repository implements every storage port on one connection: a pool for
// stand-alone calls, or a transaction inside Database.InTx.
type Repository struct {
	db   connection
	q    *sqlcgen.Queries
	opts Options
}

func newRepository(db connection, opts Options) *Repository {
	return &Repository{db: db, q: sqlcgen.New(db), opts: opts}
}

// atomic runs fn in a transaction (a savepoint when already inside one), so
// multi-statement writes are all-or-nothing wherever they are called from.
func (r *Repository) atomic(ctx context.Context, fn func(q *sqlcgen.Queries) error) error {
	return pgx.BeginFunc(ctx, r.db, func(tx pgx.Tx) error {
		return fn(sqlcgen.New(tx))
	})
}

// Database is the entry point of the adapter: a Repository on the pool that
// also runs transactions (usecase.TxRunner).
type Database struct {
	*Repository
	pool *pgxpool.Pool
	opts Options
}

// NewDatabase wires the adapter on a connection pool.
func NewDatabase(pool *pgxpool.Pool, opts Options) *Database {
	return &Database{Repository: newRepository(pool, opts), pool: pool, opts: opts}
}

// Ping checks that the database answers (readiness probe).
func (d *Database) Ping(ctx context.Context) error {
	if err := d.pool.Ping(ctx); err != nil {
		return fmt.Errorf("ping postgres: %w", err)
	}
	return nil
}

// InTx implements usecase.TxRunner: fn and the stores it receives share one
// transaction, committed when fn returns nil and rolled back otherwise.
func (d *Database) InTx(ctx context.Context, fn func(ctx context.Context, tx usecase.Stores) error) error {
	err := pgx.BeginTxFunc(ctx, d.pool, pgx.TxOptions{}, func(tx pgx.Tx) error {
		repo := newRepository(tx, d.opts)
		return fn(ctx, usecase.Stores{
			Users:       repo,
			Companies:   repo,
			Invitations: repo,
			Identities:  repo,
			Sessions:    repo,
			Audit:       repo,
		})
	})
	if err != nil {
		// %w keeps the callback's own errors (usecase and domain sentinels) matchable.
		return fmt.Errorf("transaction: %w", err)
	}
	return nil
}

var (
	_ usecase.UserFinder       = (*Repository)(nil)
	_ usecase.UserWriter       = (*Repository)(nil)
	_ usecase.UserLister       = (*Repository)(nil)
	_ usecase.CompanyMembers   = (*Repository)(nil)
	_ usecase.RoleCounter      = (*Repository)(nil)
	_ usecase.IdentityStore    = (*Repository)(nil)
	_ usecase.InvitationFinder = (*Repository)(nil)
	_ usecase.InvitationWriter = (*Repository)(nil)
	_ usecase.CompanyFinder    = (*Repository)(nil)
	_ usecase.CompanyWriter    = (*Repository)(nil)
	_ usecase.CompanyLister    = (*Repository)(nil)
	_ usecase.FarmDirectory    = (*Repository)(nil)
	_ usecase.SessionRevoker   = (*Repository)(nil)
	_ usecase.SessionStore     = (*Repository)(nil)
	_ usecase.AuditRecorder    = (*Repository)(nil)
	_ usecase.TxRunner         = (*Database)(nil)
)
